# Analyze the grid structure - look at connected components, regions
from collections import deque

def find_regions(grid):
    """Find connected components of empty space (0s) bounded by 5s"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    regions = []

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 0 and (i, j) not in visited:
                region = [(i, j)]
                q = deque([(i, j)])
                while q:
                    ri, rj = q.popleft()
                    for di, dj in [(-1,0), (1,0), (0,-1), (0,1)]:
                        ni, nj = ri + di, rj + dj
                        if 0 <= ni < rows and 0 <= nj < cols:
                            if grid[ni][nj] == 0 and (ni, nj) not in visited:
                                visited.add((ni, nj))
                                region.append((ni, nj))
                                q.append((ni, nj))
                regions.append(region)

    return regions

regions = find_regions(input_grid)
print(f"Number of zero-regions: {len(regions)}")
print(f"Largest region size: {max(len(r) for r in regions)}")

# Look at where the 1s are relative to regions
ones = [(3, 10), (4, 10), (5, 10)]
for i, (r, c) in enumerate(ones):
    # Find which region this cell is adjacent to
    adj_regions = []
    for region_idx, region in enumerate(regions):
        for (cr, cc) in region:
            if abs(cr - r) + abs(cc - c) == 1:
                adj_regions.append(region_idx)
                break
    print(f"One at ({r}, {c}): adjacent to {adj_regions} region(s)")

