# Fix the flood fill - preserve 1s exactly as they are in input
from collections import deque

def flood_fill_v2(grid, start_points):
    rows, cols = len(grid), len(grid[0])
    visited = set()

    # Add all 1s to visited initially
    for sr, sc in start_points:
        visited.add((sr, sc))

    # Find all reachable empty cells from anywhere nearby
    q = deque()
    for sr, sc in start_points:
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = sr + dr, sc + dc
            if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 0:
                visited.add((nr, nc))
                q.append((nr, nc))

    while q:
        cr, cc = q.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 0 and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    q.append((nr, nc))

    # Build result - preserve everything except replace reachable 0s
    new_grid = []
    for i in range(rows):
        new_row = []
        for j in range(cols):
            if grid[i][j] == 5:
                new_row.append(5)
            elif (i, j) in visited and grid[i][j] == 0:
                new_row.append(9)  # Fill color
            elif (i, j) in visited and grid[i][j] != 0:
                new_row.append(grid[i][j])  # Keep existing (the 1s)
            else:
                new_row.append(0)  # Unreachable empties stay 0
        new_grid.append(new_row)

    return new_grid

