# Try submitting a simple fill that extends 1s into all adjacent empty cells recursively  
def recursive_fill(grid):
    rows, cols = len(grid), len(grid[0])
    new_grid = [row[:] for row in grid]
    changed = True

    while changed:
        changed = False
        for i in range(rows):
            for j in range(cols):
                if new_grid[i][j] == 0:
                    # Check if any neighbor is 1
                    neighbors = [
                        (i-1, j), (i+1, j), (i, j-1), (i, j+1)
                    ]
                    has_one_neighbor = False
                    for ni, nj in neighbors:
                        if 0 <= ni < rows and 0 <= nj < cols and new_grid[ni][nj] == 1:
                            has_one_neighbor = True
                            break
                    if has_one_neighbor:
                        new_grid[i][j] = 1
                        changed = True

    return new_grid

recursive_filled = recursive_fill(input_grid)
print("Sample of recursive fill:")
for i, row in enumerate(recursive_filled[:5]):
    print(f"Row {i}: ... {row[8:13]} ...")

